54	const quote = (step: QuoteStep): StepResult => {
55	  const policyBasePremium = step.items.reduce(
56	    (sum, item) => sum + BASE_PREMIUMS[item.type],
57	    0,
58	  );
59	  return {
60	    premium: Math.ceil(
61	      policyBasePremium +
62	        surchargeOn(policyBasePremium, INITIAL_ASSESSMENT_SURCHARGE) +
63	        PROCESSING_FEE,
64	    ),
65	  };
66	};
