/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);

const quote = (step: QuoteStep): StepResult => {
  const policyBasePremium = step.items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  return {
    premium: roundPremiumInMHPCOFavour(
      policyBasePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE) + PROCESSING_FEE,
    ),
  };
};

